<script setup lang="ts">import { Line } from 'vue-chartjs';import { Chart as ChartJS,CategoryScale,LinearScale,PointElement,LineElement,Title,Tooltip,Legend, type ChartOptions } from 'chart.js';ChartJS.register(CategoryScale,LinearScale,PointElement,LineElement,Title,Tooltip,Legend);const props=defineProps<{labels:string[];loadData:number[];unloadData:number[];priceData:number[]}>();const data={labels:props.labels,datasets:[{label:'Berat Muatan (kg)',data:props.loadData,borderColor:'#0d9488',backgroundColor:'rgba(13,148,136,0.12)',fill:true,tension:0.3,pointRadius:3,pointBackgroundColor:'#0d9488',yAxisID:'y'},{label:'Berat Bongkar (kg)',data:props.unloadData,borderColor:'#2563eb',backgroundColor:'rgba(37,99,235,0.12)',fill:true,tension:0.3,pointRadius:3,pointBackgroundColor:'#2563eb',yAxisID:'y'},{label:'Harga Bongkar (Rp)',data:props.priceData,borderColor:'#f97316',backgroundColor:'rgba(249,115,22,0.12)',fill:true,tension:0.3,pointRadius:3,pointBackgroundColor:'#f97316',yAxisID:'y1'}]};const options:ChartOptions<'line'>={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{boxWidth:40,boxHeight:6}},tooltip:{callbacks:{label(context){const value=context.parsed.y;const label=context.dataset.label||'';if(label.includes('Harga')){return `${label}: Rp ${Number(value).toLocaleString('id-ID')}`;}return `${label}: ${Number(value).toLocaleString('id-ID')} kg`;}}}},scales:{x:{grid:{display:false}},y:{grid:{color:'#eef2f7'},beginAtZero:true,title:{display:true,text:'Kg'}},y1:{position:'right',grid:{display:false},title:{display:true,text:'Rp'},ticks:{callback:value=>typeof value==='number'?value.toLocaleString('id-ID'):value}}}};</script>
<template><div class="h-72"><Line :data="data" :options="options"/></div></template>
